\url{https://doi.org/10.4171/owr/2009/09}.
\item[S3] Official EMS Press PDF of the same Oberwolfach report; PDF pages 29--30, printed pages 521--522.
\url{https://ems.press/content/serial-article-files/46209}.
\item[S4] Tsirelson nonclassical stochastic flows; reference in the saved dated catalogue literature review.
\url{https://arxiv.org/abs/math/0402431}.
\end{itemize}
